<script setup lang="ts">
// Download menu for the data-grid toolbar: a Popover with a format picker
// (.xlsx default / .csv / .txt) + a "Tải xuống" button. It only emits the chosen
// format — Table.vue owns the actual export (gathering rows/columns). Closes after
// triggering so a repeat download re-opens cleanly.
import { ref } from "vue"
import { Button } from "../button"
import { Icon } from "../../../icons"
import { Popover, PopoverContent, PopoverTrigger } from "../popover"
import { RadioGroup, RadioGroupItem } from "../radio-group"
import { Label } from "../label"
import { Tooltip, TooltipContent, TooltipTrigger } from "../tooltip"
import type { ExportFormat } from "./composables/use-table-export"

const emit = defineEmits<{ (e: "export", format: ExportFormat): void }>()

const open = ref(false)
const format = ref<ExportFormat>("xlsx")

function onDownload() {
    emit("export", format.value)
    open.value = false
}

const options: { value: ExportFormat; label: string }[] = [
    { value: "xlsx", label: ".xlsx" },
    { value: "csv", label: ".csv" },
    { value: "txt", label: ".txt" }
]
</script>

<template>
    <Popover v-model:open="open">
        <PopoverTrigger as-child>
            <span class="inline-flex">
                <Tooltip>
                    <TooltipTrigger as-child>
                        <Button size="icon" aria-label="Tải xuống"><Icon name="download" size="18" /></Button>
                    </TooltipTrigger>
                    <TooltipContent>Tải xuống</TooltipContent>
                </Tooltip>
            </span>
        </PopoverTrigger>
        <PopoverContent align="end" class="w-64">
            <div class="flex flex-col gap-3">
                <RadioGroup v-model="format">
                    <div v-for="opt in options" :key="opt.value" class="flex items-center gap-2">
                        <RadioGroupItem :id="`export-fmt-${opt.value}`" :value="opt.value" />
                        <Label :for="`export-fmt-${opt.value}`" class="cursor-pointer">{{ opt.label }}</Label>
                    </div>
                </RadioGroup>
                <p class="text-muted-foreground text-xs">Khi tích chọn tkqc cụ thể thì sẽ tải những tkqc đó, mặc định không chọn sẽ tải hết trong bảng.</p>
                <Button class="w-full" @click="onDownload"><Icon name="download" size="16" /> Tải xuống </Button>
            </div>
        </PopoverContent>
    </Popover>
</template>
